// Destroy the condition via base pointer to exercise the virtual destructor.
// The destructor is documented to call fini(); derived classes should clean up there.
// We assume ownership of cond (fuzzer runtime hands it to us) and do not return it.
if (!cond) { FUZZ_BAIL(); }
delete cond; // triggers usbguard::RuleConditionBase::~RuleConditionBase() and derived dtor
// No outputs returned; object is destroyed.

// Initialize the condition with a concrete Interface instance.
// Use IPCClient(false) to avoid connecting; it's a concrete usbguard::Interface.
if (!cond) { FUZZ_BAIL(); }
usbguard::IPCClient client(false);
cond->init(&client);
// Persist the condition back to the pool.

// Finalize the condition. Derived classes should release resources here.
if (!cond) { FUZZ_BAIL(); }
cond->fini();
// Return the object; it remains usable (fini is typically idempotent or pre-destroy cleanup).

// Exercise the pure-virtual update through a concrete instance (cond is expected to be derived).
// Build a Rule from a fuzzed rule string; catch parse errors and bail gracefully.
if (!cond) { FUZZ_BAIL(); }
std::string rule_str = FUZZ_PARAM_STR();
if (rule_str.empty()) { rule_str = "match"; }
usbguard::Rule rule;
try {
  rule = usbguard::Rule::fromString(rule_str);
} catch (...) {
  FUZZ_BAIL();
}
( void )cond->update(rule);
// Return cond to keep it alive.

// Clone the condition; derived classes must return a heap-allocated copy.
if (!cond) { FUZZ_BAIL(); }
usbguard::RuleConditionBase* cond_clone = cond->clone();
if (!cond_clone) { FUZZ_BAIL(); }
// Return both original and clone to the pool.

// Evaluate applies negation semantics internally based on the condition state.
if (!cond) { FUZZ_BAIL(); }
std::string rule_str = FUZZ_PARAM_STR();
if (rule_str.empty()) { rule_str = "match"; }
usbguard::Rule rule;
try {
  rule = usbguard::Rule::fromString(rule_str);
} catch (...) {
  FUZZ_BAIL();
}
( void )cond->evaluate(rule);
// Return the condition.

// Access the identifier/name of the condition.
if (!cond) { FUZZ_BAIL(); }
( void )cond->identifier();
// Return the object.

// Access the parameter string (may be empty).
if (!cond) { FUZZ_BAIL(); }
( void )cond->parameter();
// Return the object.

// Query whether the condition has a non-empty parameter.
if (!cond) { FUZZ_BAIL(); }
( void )cond->hasParameter();
// Return the object.

// Query whether the condition is logically negated.
